<script lang="ts">let { data, form } = $props();</script>
<p class="eyebrow">Your profile</p><h1>Make yourself at home.</h1><div class="section-grid"><section class="card"><h2>Profile details</h2>{#if data.identity.hasAvatar}<img class="photo" src="/account/avatar?v={data.identity.avatarUpdatedAt}" alt="Your profile" />{/if}<form method="POST" enctype="multipart/form-data"><label for="name">Name</label><input id="name" name="name" required maxlength="40" value={data.identity.name} autocomplete="name" /><label for="username">Unique username</label><input id="username" name="username" required minlength="3" maxlength="24" value={data.identity.username ?? ''} autocomplete="username" autocapitalize="none" pattern="[a-zA-Z0-9_]+" /><label for="avatar">Profile picture (optional)</label><input id="avatar" name="avatar" type="file" accept="image/png,image/jpeg,image/webp" /><p class="muted">PNG, JPEG or WebP, up to 1.5 MB.</p>{#if data.identity.hasAvatar}<label><input type="checkbox" name="removeAvatar" value="yes" /> Remove current picture</label>{/if}{#if form?.message}<p class="error" role="alert">{form.message}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}<button class="button">Save profile</button></form></section><section class="card"><h2>Your account</h2><div class="account-links"><a class="secondary" href="/account/password">Change password</a><a class="secondary" href="/rooms">Create, join or switch rooms</a>{#if data.hasRoom}<a class="secondary" href="/profile">Payment methods for this room</a>{/if}<form method="POST" action="/logout"><button class="button">Sign out</button></form></div></section></div>
